package propertyrental.platform.moderation.application.mapper;

import org.springframework.stereotype.Component;

import propertyrental.platform.moderation.api.dto.request.CreateReportReasonRequest;
import propertyrental.platform.moderation.api.dto.request.UpdateReportReasonRequest;
import propertyrental.platform.moderation.api.dto.response.ReportReasonResponse;
import propertyrental.platform.moderation.infrastructure.persistence.entity.ReportReasonEntity;

@Component
public class ReportReasonMapper {

    // Thia builds a new entity from a create request (the id is generated by the database)
    public ReportReasonEntity toEntity(CreateReportReasonRequest request) {
        ReportReasonEntity reportReason = new ReportReasonEntity();
        reportReason.setCode(request.code());
        reportReason.setName(request.name());

        return reportReason;
    }

    // This applies an update request to an existing entity in place
    public void updateEntity(ReportReasonEntity reportReason, UpdateReportReasonRequest request) {
        reportReason.setCode(request.code());
        reportReason.setName(request.name());
    }

    // This converts an entity to the response DTO, so the entity is never exposed
    public ReportReasonResponse toResponse(ReportReasonEntity reportReason) {

        return new ReportReasonResponse(
                reportReason.getId(),
                reportReason.getCode(),
                reportReason.getName()
        );
    }
}
